const root = $input.first().json;
const body = root.body ?? root;

// ===== Filtros: solo mensajes entrantes del cliente =====
const evento     = body.event ?? '';
const tipoMsg    = body.message_type ?? '';
const esPrivado  = body.private ?? false;
const estadoConv = body.conversation?.status ?? body.status ?? '';

if (evento !== 'message_created' || tipoMsg !== 'incoming' || esPrivado === true) {
  return [];
}
if (estadoConv && estadoConv !== 'pending') {
  return [];
}

// ===== Extraer datos (estructura Chatwoot) =====
const conv     = body.conversation ?? {};
const sender   = body.sender ?? {};
const convId   = conv.id ?? body.conversation_id ?? '';
const cuentaId = body.account?.id ?? conv.account_id ?? '';
const inboxId  = conv.inbox_id ?? body.inbox?.id ?? '';

const telefono = (sender.phone_number ?? '').replace('+', '');

// ===== Adjuntos =====
const msgAnidado = body.conversation?.messages?.[0] ?? {};
const adjuntos = (body.attachments && body.attachments.length ? body.attachments : null)
              ?? (msgAnidado.attachments && msgAnidado.attachments.length ? msgAnidado.attachments : null)
              ?? [];

// Audio SOLO si el adjunto es de tipo audio (NO agarrar cualquier adjunto)
const audioAdj = adjuntos.find(a =>
  a.file_type === 'audio' || a.file_type === 1 ||
  (a.data_url && /\.(ogg|oga|mp3|m4a|amr|wav)/i.test(a.data_url))
) || null;

const textoMsg = body.content ?? msgAnidado.content ?? '';

// ===== Clasificación del tipo de entrada =====
let tipo;
if (audioAdj) {
  tipo = 'audio';
} else if (adjuntos.length > 0) {
  // Hay adjunto pero NO es audio: imagen, vídeo, sticker, doc, ubicación, contacto...
  tipo = 'no_soportado';
} else if (!textoMsg || !textoMsg.trim()) {
  // Sin adjunto y sin texto: mensaje vacío
  tipo = 'no_soportado';
} else {
  tipo = 'text';
}

return [{ json: {
  from:             telefono,
  message_id:       String(body.id ?? ''),
  tipo:             tipo,
  texto:            textoMsg ?? '',
  nombre:           sender.name ?? '',
  conversation_id:  String(convId),
  account_id:       String(cuentaId),
  inbox_id:         String(inboxId),
  audio_url:        audioAdj ? (audioAdj.data_url ?? '') : ''
}}];

