// La query ya devuelve en orden cronológico (antiguo -> nuevo), NO hace falta reverse
const filas = $input.all().map(i => i.json);

let texto = '';
for (const f of filas) {
  const quien = f.role === 'user' ? 'Paciente' : 'Asistente';
  texto += `${quien}: ${f.mensaje}\n`;
}

if (!texto.trim()) {
  texto = '(no hay conversación previa, es el primer mensaje)';
}

return [{ json: { historial_texto: texto } }];

// Tomar transcripcion de Groq Whisper y reescribir el campo 'texto'
const original = $('2. Parsear Meta').first().json;
let transcripcion = '';
try {
  const resp = $input.first().json;
  transcripcion = (resp.text || '').trim();
} catch (e) {
  transcripcion = '';
}
if (!transcripcion || transcripcion.length < 2) {
  transcripcion = '[NOTA DEL SISTEMA: el cliente ha enviado una nota de voz que no se ha podido transcribir. Discúlpate brevemente y pídele que lo repita o lo escriba.]';
}
return [{ json: { ...original, texto: transcripcion, audio_transcrito: true } }];

